INSERT INTO master.navigation_profiles (
    machine_id, code, name, version, status,
    base_map_name, robot_map_name, route_profile_name, stitch_profile_name, config_json)
SELECT m.id, 'TKG_PAH01A_V01_NAV', 'TKG_PAH01A_V01_NAV', 1, 'DRAFT',
       'TKG_PAH01A_V01_MAP', 'TKG_PAH01A_V01_MAP',
       'TKG_PAH01A_V01_ROUTE', 'TKG_PAH01A_V01_STITCH',
       jsonb_build_object(
           'commissioningRegistry', 'tkg_rds_variant_map_naming_v1',
           'commissioningState', 'PLANNED',
           'geometryVerified', false,
           'rdsAreaName', 'TKG_PAH01A_V01',
           'switchTransitionStation', 'TKG_PAH01A_V01_ST01',
           'layoutBindingState', 'SOURCE_BACKED',
           'sourceLayoutCode', 'CUSTOMER-PHYSICAL-V1')
FROM master.machines m
WHERE m.code = 'PAH-01-A'
ON CONFLICT (machine_id, code, version) DO UPDATE SET
    name = EXCLUDED.name,
    base_map_name = EXCLUDED.base_map_name,
    robot_map_name = EXCLUDED.robot_map_name,
    route_profile_name = EXCLUDED.route_profile_name,
    stitch_profile_name = EXCLUDED.stitch_profile_name,
    config_json = jsonb_set(
        jsonb_set(
            master.navigation_profiles.config_json || (EXCLUDED.config_json - 'commissioningState' - 'geometryVerified'),
            '{commissioningState}',
            to_jsonb(CASE
                WHEN master.navigation_profiles.config_json ->> 'commissioningState' IN ('MAPPED', 'VERIFIED', 'COMMISSIONED')
                THEN master.navigation_profiles.config_json ->> 'commissioningState'
                ELSE EXCLUDED.config_json ->> 'commissioningState'
            END)),
        '{geometryVerified}',
        to_jsonb(CASE
            WHEN coalesce((master.navigation_profiles.config_json ->> 'geometryVerified')::boolean, false)
            THEN true
            ELSE coalesce((EXCLUDED.config_json ->> 'geometryVerified')::boolean, false)
        END));

INSERT INTO master.variant_navigation_profile_assignments (
    variant_id, machine_id, navigation_profile_id, is_default)
SELECT v.id, v.machine_id, np.id, false
FROM master.machines m
JOIN master.variants v ON v.machine_id = m.id AND v.code = '1'
JOIN master.navigation_profiles np ON np.machine_id = m.id AND np.code = 'TKG_PAH01A_V01_NAV' AND np.version = 1
WHERE m.code = 'PAH-01-A'
ON CONFLICT (variant_id, navigation_profile_id) DO NOTHING;
