JOIN master.navigation_profiles np ON np.machine_id = m.id AND np.code = 'TKG_SEALER_V02_NAV' AND np.version = 1
WHERE m.code = 'SEALER'
ON CONFLICT (navigation_profile_id, planned_rds_site_id) DO UPDATE SET
    object_family = EXCLUDED.object_family,
    ordinal = EXCLUDED.ordinal,
    updated_at = now();
