INSERT INTO integration.layout_slot_rds_plan_bindings (
    layout_slot_id, navigation_profile_id, worksite_plan_id, logical_slot_code,
    business_role, source_layout_code, metadata_json)
SELECT s.id, np.id, plan.id, 'SLOT-001',
       'ALT_PART', 'CUSTOMER-PHYSICAL-V3', jsonb_build_object('partCodes', jsonb_build_array('57553F4010-40'), 'geometryVerified', false)
FROM master.machines m
JOIN master.layouts l ON l.machine_id = m.id AND l.code = 'CUSTOMER-PHYSICAL-V3'
JOIN master.layout_slots s ON s.layout_id = l.id AND s.code = 'SLOT-001'
JOIN master.navigation_profiles np ON np.machine_id = m.id AND np.code = 'TKG_412B_V03_NAV' AND np.version = 1
JOIN integration.rds_worksite_plans plan
  ON plan.navigation_profile_id = np.id
 AND plan.planned_rds_site_id = 'TKG_412B_V03_WS_P01'
WHERE m.code = '412B'
ON CONFLICT (layout_slot_id, navigation_profile_id) DO UPDATE SET
    worksite_plan_id = EXCLUDED.worksite_plan_id,
    logical_slot_code = EXCLUDED.logical_slot_code,
    business_role = EXCLUDED.business_role,
    source_layout_code = EXCLUDED.source_layout_code,
    metadata_json = EXCLUDED.metadata_json || CASE
        WHEN coalesce((integration.layout_slot_rds_plan_bindings.metadata_json ->> 'geometryVerified')::boolean, false)
        THEN jsonb_build_object('geometryVerified', true)
        ELSE '{}'::jsonb
    END,
    updated_at = now();
